    --color-accent-light: #f5ede0;
    --color-focus: #ffd700;
    --color-link: #f0f0f0;
    --color-link-hover: #e8d5b7;
    --color-button-bg: #1a1a1a;
    --color-button-border: #3a3a3a;
    --color-danger: #ff6b6b;
    --color-success: #51cf66;

    --spacing-xs: 0.5rem;
    --spacing-sm: 1rem;
    --spacing-md: 1.5rem;
    --spacing-lg: 2rem;
    --spacing-xl: 3rem;
    --spacing-2xl: 4rem;

    --transition: all 0.3s ease;
    --transition-fast: all 0.15s ease;
}

@media (prefers-color-scheme: light) {
    :root {
        --color-bg: #ffffff;
        --color-bg-secondary: #f8f8f8;
        --color-bg-tertiary: #f0f0f0;
        --color-text: #1a1a1a;
        --color-text-muted: #666;
        --color-text-subtle: #999;
        --color-border: #e0e0e0;
        --color-border-light: #f0f0f0;
        --color-accent: #c9a961;
        --color-accent-dark: #b89850;
        --color-accent-light: #e8dcc8;
    }
}

@media (forced-colors: active) {
    :root {
        --color-bg: Canvas;
        --color-text: CanvasText;
        --color-border: CanvasText;
        --color-focus: Highlight;
        --color-link: LinkText;
    }
}

/* Reset and Base Styles */
* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

html {
    scroll-behavior: smooth;
}

body {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
    background-color: var(--color-bg);
    color: var(--color-text);
    line-height: 1.6;
    letter-spacing: 0.5px;
}

/* Screen Reader Only */
.sr-only:not(:focus):not(:active) {
    clip: rect(0 0 0 0);
    clip-path: inset(50%);
    height: 1px;
    overflow: hidden;
    position: absolute;
    white-space: nowrap;
    width: 1px;
}

/* Skip Link */
.skip-link {
    position: absolute;
    top: -40px;
    left: 0;
    background-color: var(--color-accent);
    color: var(--color-bg);
    padding: var(--spacing-sm) var(--spacing-md);
    text-decoration: none;
    font-weight: 600;
    z-index: 1000;
}

.skip-link:focus {
    top: 0;
    outline: 2px solid var(--color-focus);
    outline-offset: 2px;
}

@media (forced-colors: active) {
    .skip-link:focus {
        outline: 3px solid Highlight;
    }
}

/* Header */
.header {
    background-color: var(--color-bg-secondary);
    border-bottom: 1px solid var(--color-border);
    position: sticky;
    top: 0;
    z-index: 100;
}

.header-content {
    max-width: 1400px;
    margin: 0 auto;
    padding: var(--spacing-md) var(--spacing-lg);
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: var(--spacing-lg);
}

.logo-section {
    flex: 1;
}

.logo {
    font-size: 1.5rem;
    font-weight: 700;
    letter-spacing: 2px;
    color: var(--color-accent);
    margin: 0;
}

.tagline {
    font-size: 0.8rem;
    color: var(--color-text-muted);
    margin: 0.25rem 0 0 0;
    letter-spacing: 1px;
    text-transform: uppercase;
}

/* Navigation */
.primary-nav {
    flex: 2;
}

.nav-toggle {
    display: none;
    background: none;
    border: none;
    color: var(--color-text);
    cursor: pointer;
    padding: var(--spacing-xs);
    width: 44px;
    height: 44px;
    align-items: center;
    justify-content: center;
}

.nav-toggle:focus {
    outline: 2px solid var(--color-focus);
    outline-offset: 2px;
}

@media (forced-colors: active) {
    .nav-toggle:focus {
        outline: 3px solid Highlight;
    }
}

.nav-menu {
    display: flex;
    list-style: none;
    gap: var(--spacing-lg);
}

.nav-menu a {
    color: var(--color-text);
