/* CSS Custom Properties - Color Tokens */
:root {
    --color-bg: #0a0a0a;
    --color-bg-secondary: #141414;
    --color-bg-tertiary: #1f1f1f;
    --color-text: #f5f5f5;
    --color-text-muted: #a8a8a8;
    --color-text-subtle: #7a7a7a;
    --color-border: #2a2a2a;
    --color-border-light: #3a3a3a;
    --color-accent: #e8d5b7;
    --color-accent-dark: #d4c5a9;
    --color-accent-light: #f5ede0;
    --color-focus: #ffd700;
    --color-link: #f0f0f0;
    --color-link-hover: #e8d5b7;
    --color-button-bg: #1a1a1a;
    --color-button-border: #3a3a3a;
    --color-danger: #ff6b6b;
    --color-success: #51cf66;

    --spacing-xs: 0.5rem;
    --spacing-sm: 1rem;
    --spacing-md: 1.5rem;
    --spacing-lg: 2rem;
    --spacing-xl: 3rem;
    --spacing-2xl: 4rem;

    --transition: all 0.3s ease;
    --transition-fast: all 0.15s ease;
}

@media (prefers-color-scheme: light) {
    :root {
        --color-bg: #ffffff;
        --color-bg-secondary: #f8f8f8;
        --color-bg-tertiary: #f0f0f0;
        --color-text: #1a1a1a;
        --color-text-muted: #666;
        --color-text-subtle: #999;
        --color-border: #e0e0e0;
        --color-border-light: #f0f0f0;
        --color-accent: #c9a961;
        --color-accent-dark: #b89850;
        --color-accent-light: #e8dcc8;
    }
}

@media (forced-colors: active) {
    :root {
        --color-bg: Canvas;
        --color-text: CanvasText;
        --color-border: CanvasText;
        --color-focus: Highlight;
        --color-link: LinkText;
    }
}

/* Reset and Base Styles */
* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

html {
    scroll-behavior: smooth;
}

body {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
    background-color: var(--color-bg);
    color: var(--color-text);
    line-height: 1.6;
    letter-spacing: 0.5px;
}

/* Screen Reader Only */
.sr-only:not(:focus):not(:active) {
    clip: rect(0 0 0 0);
    clip-path: inset(50%);
    height: 1px;
    overflow: hidden;
    position: absolute;
    white-space: nowrap;
    width: 1px;
}

/* Skip Link */
.skip-link {
    position: absolute;
    top: -40px;
    left: 0;
    background-color: var(--color-accent);
    color: var(--color-bg);
    padding: var(--spacing-sm) var(--spacing-md);
    text-decoration: none;
    font-weight: 600;
    z-index: 1000;
}

.skip-link:focus {
    top: 0;
    outline: 2px solid var(--color-focus);
    outline-offset: 2px;
}

@media (forced-colors: active) {
    .skip-link:focus {
        outline: 3px solid Highlight;
    }
}

/* Header */
.header {
    background-color: var(--color-bg-secondary);
    border-bottom: 1px solid var(--color-border);
    position: sticky;
    top: 0;
    z-index: 100;
}

.header-content {
    max-width: 1400px;
    margin: 0 auto;
    padding: var(--spacing-md) var(--spacing-lg);
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: var(--spacing-lg);
}

.logo-section {
    flex: 1;
}

.logo {
    font-size: 1.5rem;
    font-weight: 700;
    letter-spacing: 2px;
    color: var(--color-accent);
    margin: 0;
}

.tagline {
    font-size: 0.8rem;
    color: var(--color-text-muted);
    margin: 0.25rem 0 0 0;
    letter-spacing: 1px;
    text-transform: uppercase;
}

/* Navigation */
.primary-nav {
    flex: 2;
}

.nav-toggle {
    display: none;
    background: none;
    border: none;
    color: var(--color-text);
    cursor: pointer;
    padding: var(--spacing-xs);
    width: 44px;
    height: 44px;
    align-items: center;
    justify-content: center;
}

.nav-toggle:focus {
    outline: 2px solid var(--color-focus);
    outline-offset: 2px;
}

@media (forced-colors: active) {
    .nav-toggle:focus {
        outline: 3px solid Highlight;
    }
}

.nav-menu {
    display: flex;
    list-style: none;
    gap: var(--spacing-lg);
}

.nav-menu a {
    color: var(--color-text);
    text-decoration: none;
    font-size: 0.95rem;
    padding: var(--spacing-xs) var(--spacing-sm);
    transition: var(--transition);
    display: inline-block;
}

.nav-menu a:hover {
    color: var(--color-accent);
}

.nav-menu a:focus {
    outline: 2px solid var(--color-focus);
    outline-offset: 2px;
}

/* Header Actions */
.header-actions {
    display: flex;
    gap: var(--spacing-md);
}

.action-btn {
    background: none;
    border: none;
    color: var(--color-text);
    cursor: pointer;
    padding: var(--spacing-xs);
    width: 44px;
    height: 44px;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: var(--transition);
}

.action-btn:hover {
    color: var(--color-accent);
}

.action-btn:focus {
    outline: 2px solid var(--color-focus);
    outline-offset: 2px;
}

@media (forced-colors: active) {
    .action-btn:focus {
        outline: 3px solid Highlight;
    }
}

/* Hero Section */
.hero {
    background: linear-gradient(135deg, var(--color-bg-secondary) 0%, var(--color-bg-tertiary) 100%);
    padding: var(--spacing-2xl) var(--spacing-lg);
    text-align: center;
    min-height: 400px;
    display: flex;
    align-items: center;
    justify-content: center;
    position: relative;
    overflow: hidden;
}

.hero::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: radial-gradient(circle at 30% 50%, rgba(232, 213, 183, 0.1) 0%, transparent 50%);
    pointer-events: none;
}

.hero-content {
    position: relative;
    z-index: 1;
    max-width: 600px;
}

.hero h2 {
    font-size: 3rem;
    font-weight: 700;
    margin-bottom: var(--spacing-md);
    color: var(--color-text);
    letter-spacing: 1px;
}

.hero p {
    font-size: 1.2rem;
    color: var(--color-text-muted);
    margin-bottom: var(--spacing-lg);
}

.cta-btn {
    background-color: var(--color-accent);
    color: var(--color-bg);
    border: none;
    padding: var(--spacing-md) var(--spacing-xl);
    font-size: 1rem;
    font-weight: 600;
    cursor: pointer;
    transition: var(--transition);
    text-transform: uppercase;
    letter-spacing: 1px;
}

.cta-btn:hover {
    background-color: var(--color-accent-dark);
    transform: translateY(-2px);
}

.cta-btn:focus {
    outline: 2px solid var(--color-focus);
    outline-offset: 2px;
}

@media (forced-colors: active) {
    .cta-btn {
        border: 2px solid ButtonBorder;
    }
    .cta-btn:focus {
        outline: 3px solid Highlight;
    }
}

/* Sections */
.products-section,
.deals-section,
.editorial-section,
.newsletter-section {
    max-width: 1400px;
    margin: 0 auto;
    padding: var(--spacing-2xl) var(--spacing-lg);
}

.section-header {
    text-align: center;
    margin-bottom: var(--spacing-2xl);
}

.section-header h2 {
    font-size: 2.5rem;
    font-weight: 700;
    margin-bottom: var(--spacing-md);
    color: var(--color-text);
    letter-spacing: 0.5px;
}

.section-description {
    font-size: 1.1rem;
    color: var(--color-text-muted);
}

/* Products Section */
.products-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
    gap: var(--spacing-lg);
}

.product-card {
    background-color: var(--color-bg-secondary);
    border: 1px solid var(--color-border);
    transition: var(--transition);
    display: flex;
    flex-direction: column;
}

.product-card:hover {
    border-color: var(--color-accent);
    transform: translateY(-4px);
}

.product-image {
    width: 100%;
    aspect-ratio: 3 / 4;
    overflow: hidden;
    background-color: var(--color-bg-tertiary);
}

.product-image img {
    width: 100%;
    height: 100%;
    object-fit: cover;
}

.product-info {
    padding: var(--spacing-md);
    flex-grow: 1;
    display: flex;
    flex-direction: column;
}

.product-info h3 {
    font-size: 1.1rem;
    font-weight: 600;
    margin-bottom: var(--spacing-sm);
}

.product-info h3 a {
    color: var(--color-text);
    text-decoration: none;
    transition: var(--transition);
}

.product-info h3 a:hover {
    color: var(--color-accent);
}

.product-info h3 a:focus {
    outline: 2px solid var(--color-focus);
    outline-offset: 2px;
}

.product-category {
    font-size: 0.85rem;
    color: var(--color-text-subtle);
    text-transform: uppercase;
    letter-spacing: 0.5px;
    margin-bottom: var(--spacing-sm);
}

.product-price {
    margin-bottom: var(--spacing-md);
    flex-grow: 1;
}

.price {
    font-size: 1.3rem;
    font-weight: 700;
    color: var(--color-accent);
}

.add-to-cart-btn {
    background-color: var(--color-button-bg);
    color: var(--color-accent);
    border: 1px solid var(--color-button-border);
    padding: var(--spacing-sm) var(--spacing-md);
    cursor: pointer;
    transition: var(--transition);
    text-transform: uppercase;
    font-size: 0.9rem;
    font-weight: 600;
    letter-spacing: 0.5px;
}

.add-to-cart-btn:hover {
    background-color: var(--color-accent);
    color: var(--color-bg);
    border-color: var(--color-accent);
}

.add-to-cart-btn:focus {
    outline: 2px solid var(--color-focus);
    outline-offset: 2px;
}

@media (forced-colors: active) {
    .add-to-cart-btn {
        border: 2px solid ButtonBorder;
    }
    .add-to-cart-btn:focus {
        outline: 3px solid Highlight;
    }
}

/* Deals Section */
.deals-container {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
    gap: var(--spacing-lg);
}

.deal-card {
    background: linear-gradient(135deg, var(--color-bg-tertiary) 0%, var(--color-bg-secondary) 100%);
    border: 1px solid var(--color-border-light);
    padding: var(--spacing-lg);
    position: relative;
    overflow: hidden;
    transition: var(--transition);
}

.deal-card:hover {
    border-color: var(--color-accent);
    transform: translateY(-4px);
}

.deal-primary {
    background: linear-gradient(135deg, var(--color-accent) 0%, var(--color-accent-dark) 100%);
    color: var(--color-bg);
    border-color: var(--color-accent-dark);
}

.deal-primary h3 {
    color: var(--color-bg);
}

.deal-primary p {
    color: rgba(0, 0, 0, 0.8);
}

.deal-badge {
    display: inline-block;
    background-color: var(--color-bg);
    color: var(--color-accent);
    padding: var(--spacing-xs) var(--spacing-sm);
    font-size: 0.8rem;
    font-weight: 700;
    text-transform: uppercase;
    margin-bottom: var(--spacing-md);
    letter-spacing: 1px;
}

.deal-primary .deal-badge {
    background-color: rgba(255, 255, 255, 0.2);
    color: var(--color-bg);
}

.deal-card h3 {
    font-size: 1.5rem;
    margin-bottom: var(--spacing-sm);
}

.deal-card p {
    color: var(--color-text-muted);
    margin-bottom: var(--spacing-md);
}

.deal-btn {
    background-color: var(--color-accent);
    color: var(--color-bg);
    border: none;
    padding: var(--spacing-sm) var(--spacing-lg);
    cursor: pointer;
    font-weight: 600;
    transition: var(--transition);
    text-transform: uppercase;
    font-size: 0.9rem;
    letter-spacing: 0.5px;
}

.deal-card:not(.deal-primary) .deal-btn {
    background-color: var(--color-button-bg);
    color: var(--color-accent);
    border: 1px solid var(--color-button-border);
}

.deal-btn:hover {
    transform: translateY(-2px);
}

.deal-btn:focus {
    outline: 2px solid var(--color-focus);
    outline-offset: 2px;
}

@media (forced-colors: active) {
    .deal-btn {
        border: 2px solid ButtonBorder;
    }
    .deal-btn:focus {
        outline: 3px solid Highlight;
    }
}

/* Editorial Section */
.editorial-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
    gap: var(--spacing-lg);
}

.editorial-card {
    background-color: var(--color-bg-secondary);
    border: 1px solid var(--color-border);
    overflow: hidden;
    transition: var(--transition);
    display: flex;
    flex-direction: column;
}

.editorial-card:hover {
    border-color: var(--color-accent);
}

.editorial-image {
    width: 100%;
    aspect-ratio: 16 / 10;
    overflow: hidden;
    background-color: var(--color-bg-tertiary);
}

.editorial-image img {
    width: 100%;
    height: 100%;
    object-fit: cover;
}

.editorial-content {
    padding: var(--spacing-lg);
    flex-grow: 1;
    display: flex;
    flex-direction: column;
}

.editorial-category {
    display: inline-block;
    font-size: 0.75rem;
    text-transform: uppercase;
    color: var(--color-accent);
    font-weight: 700;
    margin-bottom: var(--spacing-sm);
    letter-spacing: 1px;
}

.editorial-card h3 {
    font-size: 1.3rem;
    margin-bottom: var(--spacing-sm);
    line-height: 1.4;
}

.editorial-card h3 a {
    color: var(--color-text);
    text-decoration: none;
    transition: var(--transition);
}

.editorial-card h3 a:hover {
    color: var(--color-accent);
}

.editorial-card h3 a:focus {
    outline: 2px solid var(--color-focus);
    outline-offset: 2px;
}

.editorial-card p {
    color: var(--color-text-muted);
    margin-bottom: var(--spacing-md);
    flex-grow: 1;
}

.read-more {
    color: var(--color-accent);
    text-decoration: none;
    font-weight: 600;
    transition: var(--transition);
}

.read-more:hover {
    color: var(--color-accent-light);
}

.read-more:focus {
    outline: 2px solid var(--color-focus);
    outline-offset: 2px;
}

/* Newsletter Section */
.newsletter-section {
    background: linear-gradient(135deg, var(--color-bg-secondary) 0%, var(--color-bg-tertiary) 100%);
    text-align: center;
}

.newsletter-content {
    max-width: 600px;
    margin: 0 auto;
}

.newsletter-content h2 {
    font-size: 2rem;
    margin-bottom: var(--spacing-md);
}

.newsletter-content p {
    color: var(--color-text-muted);
    margin-bottom: var(--spacing-lg);
}

.newsletter-form {
    display: flex;
    flex-direction: column;
    gap: var(--spacing-sm);
}

.newsletter-form input {
    padding: var(--spacing-md);
    background-color: var(--color-bg);
    border: 1px solid var(--color-border);
    color: var(--color-text);
    font-size: 1rem;
    transition: var(--transition);
}

.newsletter-form input::placeholder {
    color: var(--color-text-subtle);
}

.newsletter-form input:focus {
    outline: 2px solid var(--color-focus);
    outline-offset: 2px;
    border-color: var(--color-accent);
}

@media (forced-colors: active) {
    .newsletter-form input:focus {
        outline: 3px solid Highlight;
    }
}

.subscribe-btn {
    background-color: var(--color-accent);
    color: var(--color-bg);
    border: none;
    padding: var(--spacing-md);
    font-size: 1rem;
    font-weight: 600;
    cursor: pointer;
    transition: var(--transition);
    text-transform: uppercase;
    letter-spacing: 1px;
}

.subscribe-btn:hover {
    background-color: var(--color-accent-dark);
}

.subscribe-btn:focus {
    outline: 2px solid var(--color-focus);
    outline-offset: 2px;
}

@media (forced-colors: active) {
    .subscribe-btn:focus {
        outline: 3px solid Highlight;
    }
}

.form-help {
    font-size: 0.85rem;
    color: var(--color-text-subtle);
    margin: 0;
}

/* Footer */
.footer {
    background-color: var(--color-bg-secondary);
    border-top: 1px solid var(--color-border);
    margin-top: var(--spacing-2xl);
}

.footer-content {
    max-width: 1400px;
    margin: 0 auto;
    padding: var(--spacing-2xl) var(--spacing-lg);
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
    gap: var(--spacing-lg);
}

.footer-section h3 {
    font-size: 1rem;
    text-transform: uppercase;
    margin-bottom: var(--spacing-md);
    letter-spacing: 1px;
    color: var(--color-text);
}

.footer-section ul {
    list-style: none;
}

.footer-section li {
    margin-bottom: var(--spacing-sm);
}

.footer-section a {
    color: var(--color-text-muted);
    text-decoration: none;
    transition: var(--transition);
}

.footer-section a:hover {
    color: var(--color-accent);
}

.footer-section a:focus {
    outline: 2px solid var(--color-focus);
    outline-offset: 2px;
}

.social-links {
    display: flex;
    gap: var(--spacing-md);
}

.footer-bottom {
    text-align: center;
    padding: var(--spacing-lg);
    border-top: 1px solid var(--color-border);
    color: var(--color-text-muted);
    font-size: 0.9rem;
}

/* Responsive Design */
@media (max-width: 768px) {
    .header-content {
        gap: var(--spacing-md);
    }

    .nav-toggle {
        display: flex;
    }

    .nav-menu {
        display: none;
        position: absolute;
        top: 100%;
        left: 0;
        right: 0;
        background-color: var(--color-bg-secondary);
        flex-direction: column;
        padding: var(--spacing-md);
        border-bottom: 1px solid var(--color-border);
        gap: 0;
    }

    .nav-menu.active {
        display: flex;
    }

    .nav-menu a {
        padding: var(--spacing-md);
    }

    .hero h2 {
        font-size: 2rem;
    }

    .hero p {
        font-size: 1rem;
    }

    .section-header h2 {
        font-size: 1.8rem;
    }

    .products-grid {
        grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
        gap: var(--spacing-md);
    }

    .newsletter-form {
        flex-direction: column;
    }

    .newsletter-form input {
        width: 100%;
    }
}

@media (max-width: 480px) {
    body {
        font-size: 0.95rem;
    }

    .header-content {
        flex-direction: column;
        gap: var(--spacing-sm);
    }

    .logo {
        font-size: 1.2rem;
    }

    .header-actions {
        gap: var(--spacing-sm);
    }

    .hero {
        padding: var(--spacing-lg) var(--spacing-md);
        min-height: 300px;
    }

    .hero h2 {
        font-size: 1.5rem;
    }

    .products-section,
    .deals-section,
    .editorial-section,
    .newsletter-section {
        padding: var(--spacing-lg) var(--spacing-md);
    }

    .section-header h2 {
        font-size: 1.5rem;
    }

    .products-grid {
        grid-template-columns: 1fr;
    }

    .deals-container {
        grid-template-columns: 1fr;
    }

    .editorial-grid {
        grid-template-columns: 1fr;
    }
}

/* Print Styles */
@media print {
    .header,
    .footer,
    .nav-toggle,
    .header-actions {
        display: none;
    }

    .skip-link {
        display: none;
    }

    main {
        max-width: 100%;
    }
}

/* Reduced Motion */
@media (prefers-reduced-motion: reduce) {
    * {
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.01ms !important;
    }
}

