        if (h1Count !== 1) {
            issues.push(`Found ${h1Count} h1 elements (should be 1)`);
        }

        // Check main element
        const mainCount = document.querySelectorAll('main').length;
        if (mainCount !== 1) {
            issues.push(`Found ${mainCount} main elements (should be 1)`);
        }

